from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    foreground = next(value for value in counts if value != background)
    out = [row[:] for row in grid]

    bands = []
    r = 0
    while r < h:
        while r < h and foreground not in grid[r]:
            r += 1
        if r == h:
            break
        start = r
        while r < h and foreground in grid[r]:
            r += 1
        bands.append((start, r))

    shift_limit = min(8, w // 2)
    for i, (a0, a1) in enumerate(bands):
        for b0, b1 in bands[i + 1:]:
            if a1 - a0 != b1 - b0:
                continue
            alignments = []
            for shift in range(-shift_limit, shift_limit + 1):
                pairs = [(grid[a0 + dr][c], grid[b0 + dr][c + shift])
                         for dr in range(a1 - a0) for c in range(w)
                         if 0 <= c + shift < w]
                score = sum(a == b for a, b in pairs) / len(pairs)
                alignments.append((score, -abs(shift), shift))
            score, _, shift = max(alignments)
            if score < 0.60:
                continue

            for dr in range(a1 - a0):
                ra, rb = a0 + dr, b0 + dr
                row_a, row_b = grid[ra], grid[rb]
                marks_a = [c for c, v in enumerate(row_a) if v == foreground]
                marks_b = [c for c, v in enumerate(row_b) if v == foreground]
                if not marks_a or not marks_b:
                    continue
                end_a = max(marks_a)
                end_b_in_a = max(marks_b) - shift
                if end_a > end_b_in_a:
                    for c in marks_a:
                        target = c + shift
                        if c > end_b_in_a and 0 <= target < w and out[rb][target] == background:
                            out[rb][target] = 1
                elif end_b_in_a > end_a:
                    for c in marks_b:
                        target = c - shift
                        if target > end_a and 0 <= target < w and out[ra][target] == background:
                            out[ra][target] = 1

    for r, row in enumerate(grid):
        prefix = 0
        while prefix < w and row[prefix] == foreground:
            prefix += 1
        if prefix and prefix < w and any(
            other != r and all(grid[other][c] == foreground for c in range(prefix, w))
            for other in range(h)
        ):
            for c in range(prefix, w):
                if row[c] == background:
                    out[r][c] = 1

    return out

